sys_script_fix.script:
var eventId = 'EVT0001010'; // Replace with the actual Event sys_id

var attendeeGR = new GlideRecord('x_1790229_event_ma_attendee'); // Replace with your Attendee table name
attendeeGR.addQuery('u_event_id.number', eventId); // Assuming 'u_event' is the reference field to the Event
attendeeGR.query();

while (attendeeGR.next()) {
    gs.info('Attendee  FirstName: ' + attendeeGR.getDisplayValue('u_first_name'));
    gs.info('Email: ' + attendeeGR.getValue('u_email')); // Adjust field names accordingly

}
